func TestOpenCreatesUsableStore(t *testing.T) {
	st, err := Open("ignored-path")
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer st.Close()
	if err := st.Ping(); err != nil {
		t.Fatalf("ping: %v", err)
	}
