package api

import (
	"net/http"
	"testing"
)

func reqSpec(t *testing.T, router http.Handler, method, target string, body map[string]any) map[string]any {
	t.Helper()
	rec := lifecycleRequest(t, router, method, target, body)
	if rec.Code != 200 {
		t.Fatalf("%s %s -> %d %s", method, target, rec.Code, rec.Body.String())
	}
	return decodeLifecycleBody(t, rec)
}

func TestSpecWeightZeroRejectedAndRecordKept(t *testing.T) {
	router, st := lifecycleRouter(t)
	register(t, router, goodRegistration()) // weight 7, healthy true

	rec := lifecycleRequest(t, router, http.MethodPost, "/api/v1/register", func() map[string]any {
		b := goodRegistration()
		b["weight"] = 0
		return b
	}())
	if rec.Code != 400 {
		t.Fatalf("weight 0 register status = %d", rec.Code)
	}
	errObj := decodeLifecycleBody(t, rec)["error"].(map[string]any)
	if errObj["code"] != "INVALID_ARGUMENT" {
		t.Fatalf("code = %v", errObj["code"])
	}
	got, _, _ := st.GetInstance("svc", "i-1")
	if got.Weight != 7 || !got.Healthy {
		t.Fatalf("record changed after invalid register: %+v", got)
	}

	// heartbeat with weight 0 must also fail and leave record untouched.
	rec = lifecycleRequest(t, router, http.MethodPost, "/api/v1/heartbeat", map[string]any{
		"service_name": "svc", "instance_id": "i-1", "weight": 0,
		"request_at": lifecycleAt(2), "heartbeat_at": lifecycleAt(2),
	})
	if rec.Code != 400 {
		t.Fatalf("weight 0 heartbeat status = %d %s", rec.Code, rec.Body.String())
	}
	got, _, _ = st.GetInstance("svc", "i-1")
	if got.Weight != 7 {
		t.Fatalf("record changed after invalid heartbeat: %+v", got)
	}
}

func TestSpecHealthyOnlyAcceptsBooleans(t *testing.T) {
	router, st := lifecycleRouter(t)
	register(t, router, goodRegistration())
	for _, value := range []any{2, 1, 0, "healthy", "unhealthy", "yes", "maybe", nil} {
		body := map[string]any{
			"service_name": "svc", "instance_id": "i-1", "host": "h", "port": 9,
			"weight": 5, "healthy": value, "request_at": lifecycleBaseTime,
		}
		if value == nil {
			delete(body, "healthy")
		}
		rec := lifecycleRequest(t, router, http.MethodPost, "/api/v1/register", body)
		if value == nil {
			if rec.Code != 200 {
				t.Fatalf("missing healthy should default false: %d %s", rec.Code, rec.Body.String())
			}
			continue
		}
		if rec.Code != 400 {
			t.Fatalf("healthy=%v should be INVALID_ARGUMENT, got %d %s", value, rec.Code, rec.Body.String())
		}
	}
	got, _, _ := st.GetInstance("svc", "i-1")
	if got.Weight != 7 || !got.Healthy {
		t.Fatalf("invalid healthy values changed record: %+v", got)
	}
}

func TestSpecHeartbeatReinstatesAndWeightAffectsOrderOnly(t *testing.T) {
	router, _ := lifecycleRouter(t)
	// i-a weight 10; i-b weight 5. Both initially fresh and healthy.
	registerForDiscovery(t, router, "svc", "i-a", true, 10, lifecycleAt(0), "a")
	registerForDiscovery(t, router, "svc", "i-b", true, 5, lifecycleAt(0), "b")

	// At 12:10 timeout 5m: deadline 12:05, both are lost -> empty.
	out := discover(t, router, "/api/v1/discover?service_name=svc&evaluate_at="+lifecycleAt(10)+"&heartbeat_timeout=5m")
	if ids := discoverIDs(t, out); len(ids) != 0 {
		t.Fatalf("both lost, got %v", ids)
	}

	// Only i-a sends a new heartbeat. Weight lowered to 1. It becomes eligible;
	// i-b must NOT be resurrected.
	reqSpec(t, router, http.MethodPost, "/api/v1/heartbeat", map[string]any{
		"service_name": "svc", "instance_id": "i-a", "healthy": true, "weight": 1,
		"heartbeat_at": lifecycleAt(9), "request_at": lifecycleAt(9),
	})
	out = discover(t, router, "/api/v1/discover?service_name=svc&evaluate_at="+lifecycleAt(10)+"&heartbeat_timeout=5m")
	if ids := discoverIDs(t, out); len(ids) != 1 || ids[0] != "i-a" {
		t.Fatalf("only i-a should be eligible after its heartbeat: %v", ids)
	}

	// i-b recovers with high weight 100 -> ordering by weight puts b first.
	reqSpec(t, router, http.MethodPost, "/api/v1/heartbeat", map[string]any{
		"service_name": "svc", "instance_id": "i-b", "healthy": true, "weight": 100,
		"heartbeat_at": lifecycleAt(9), "request_at": lifecycleAt(9),
	})
	out = discover(t, router, "/api/v1/discover?service_name=svc&evaluate_at="+lifecycleAt(10)+"&heartbeat_timeout=5m")
	ids := discoverIDs(t, out)
	if len(ids) != 2 || ids[0] != "i-b" || ids[1] != "i-a" {
		t.Fatalf("weight ordering wrong: %v", ids)
	}
}

func TestSpecCleanupDoesNotResurrectOthers(t *testing.T) {
	router, st := lifecycleRouter(t)
	registerForDiscovery(t, router, "svc", "gone", true, 5, lifecycleAt(-10), "g")
	registerForDiscovery(t, router, "svc", "keep", true, 5, lifecycleAt(5), "k")

	rec := lifecycleRequest(t, router, http.MethodPost, "/api/v1/cleanup", map[string]any{
		"service_name": "svc", "evaluate_at": lifecycleAt(10), "heartbeat_timeout": "10m",
	})
	out := decodeLifecycleBody(t, rec)
	ids := out["deleted_instance_ids"].([]any)
	if len(ids) != 1 || ids[0] != "gone" {
		t.Fatalf("cleanup ids = %v", ids)
	}
	if _, found, _ := st.GetInstance("svc", "keep"); !found {
		t.Fatalf("online instance removed")
	}
	// Heartbeat for the gone instance cannot revive it (unknown now).
	hb := reqSpec(t, router, http.MethodPost, "/api/v1/heartbeat", map[string]any{
		"service_name": "svc", "instance_id": "gone", "healthy": true, "weight": 1,
		"heartbeat_at": lifecycleAt(10), "request_at": lifecycleAt(10),
	})
	if hb["updated"] != false {
		t.Fatalf("cleaned instance heartbeat must report updated=false: %v", hb)
	}
	if list, _ := st.ListInstances("svc"); len(list) != 1 {
		t.Fatalf("gone instance was resurrected")
	}
}

func TestSpecResultFieldsAndEmptyUnknownService(t *testing.T) {
	router, _ := lifecycleRouter(t)
	registerForDiscovery(t, router, "svc", "i-1", true, 3, lifecycleAt(9), "10.0.0.9")
	out := discover(t, router, "/api/v1/discover?service_name=svc&evaluate_at="+lifecycleAt(10)+"&heartbeat_timeout=10m")
	item := out["instances"].([]any)[0].(map[string]any)
	for _, key := range []string{"instance_id", "address", "port", "weight", "heartbeat_at"} {
		if _, ok := item[key]; !ok {
			t.Fatalf("missing field %s in %v", key, item)
		}
	}
	if item["address"] != "10.0.0.9:8080" || item["port"].(float64) != 8080 {
		t.Fatalf("address/port mismatch: %v", item)
	}
	out = discover(t, router, "/api/v1/discover?service_name=nope&evaluate_at="+lifecycleAt(10)+"&heartbeat_timeout=10m")
	if len(out["instances"].([]any)) != 0 {
		t.Fatalf("unknown service must return empty list: %v", out)
	}
}
